def clean_panel(raw_close, split, dividend, listed, min_adv_gbp, adv_gbp, window=60):
    """Total returns kept only when the share was in the point-in-time
    universe at the previous close (held overnight into that day)."""
    p = {"listed": listed}
    if isinstance(adv_gbp, pd.DataFrame):
        p["volume_gbp"] = adv_gbp          # a daily £ volume
    else:
        p["adv_gbp"] = adv_gbp             # one figure per share
    held = universe_mask(p, min_adv_gbp, window).shift(1, fill_value=False)
    return total_return(raw_close, split, dividend).where(held)
